-- ============================================================================
-- H5 GO-LIVE (HELD): Quantitative Risk Assessment flips to 'available', the
-- FIFTH and last course of the HSE module, at path_order 65.
--
-- DEPLOY GATE. Do NOT run this until a NextGen production upload carries the
-- route /dashboard/apps/qra. The 78 lessons, the teaching lab (qraLab.js) and
-- its three explorer panels (the event tree and individual risk builder, the
-- societal risk explorer and the ALARP and cost-benefit explorer) ship in the
-- ZIP and NOT in this database, so a flip before the upload puts a live
-- catalogue tile in front of a route that does not exist. This file is
-- written, dry-run and left unapplied on purpose.
--
-- EVERY GRADED VALUE IS CHECKED THREE WAYS, and none restates the generator:
--
--   1. against the ENGINE LEDGER: the values h5_capstone.mjs returned through
--      the vendored engines/hse/qra.js when this file was generated, to the
--      last bit, so a capstone row an earlier seed left behind, or a move of
--      one part in 1e7, is refused by name;
--   2. by a SECOND ROUTE IN SQL over the inputs the learner is handed: the
--      go-live first proves each shipped prompt is the rendered one byte for
--      byte and carries every input fragment, then recomputes the event trees
--      as products of their branches, each LSIR and IRPA as its sum, the PLL,
--      the FAR, the frequency of N or more, the corner ratios to the line and
--      the crossing, the ratio to the R2P2 point, and every present value
--      year by year, the ICAF over the undiscounted fatalities prevented;
--   3. by the TRAPS the course is built on, 91 wrong methods, each of which
--      must bite on these inputs: the reading a learner who missed the lesson
--      would give is computed and refused if it lands within the field's
--      tolerance.
--
-- THE GRADER IS NUMERIC. academy_submit_capstone casts expected, tol and the
-- answer to numeric and passes abs(answer - expected) <= tol. Per-year values
-- are graded at twelve decimals (tolerance 5e-13), FAR, ratios and fatality
-- counts at six (5e-7) and money at two (0.005). Every field must carry a
-- positive, non-whole expected value at its class's tolerance with a label and
-- a unit, the answer the prompt asks for must pass, and one unit either side
-- of it in the last asked decimal must fail. All of it is asserted here, on
-- the rows as seeded.
--
-- EVERY DENOMINATOR BELOW IS A FLOAT, ON PURPOSE. Postgres divides integer by
-- integer as an integer, and the generator refuses to emit a bare integer
-- denominator.
--
-- EVERY REFUSAL THAT READS A GRADED VALUE NAMES IT as tier/key.
-- ============================================================================

do $$
declare
  v_structures int; v_questions int; v_capstones int; v_lessons int;
  v_modules int; v_graded int; v_available int; v_soon int; v_n int; v_k int;
  v_names text; v_prompt text; v_x double precision; v_wrong double precision;
  v_g_ukpokiti_compressor_explosion_frequency_per_yr double precision;
  v_g_ukpokiti_camp_exposure_frequency_per_yr double precision;
  v_g_ukpokiti_control_room_lsir_per_yr double precision;
  v_g_ukpokiti_compressor_deck_lsir_per_yr double precision;
  v_g_ukpokiti_operator_irpa_per_yr double precision;
  v_g_ukpokiti_technician_irpa_per_yr double precision;
  v_g_ogini_crew_pll_per_yr double precision;
  v_g_ogini_crew_far double precision;
  v_g_ogini_village_frequency_ten_or_more_per_yr double precision;
  v_g_ogini_village_vrom_max_ratio double precision;
  v_g_ogini_village_exceedance_from_fatalities double precision;
  v_g_ogini_village_r2p2_point_ratio double precision;
  v_g_ebughu_deluge_cost_to_benefit_ratio double precision;
  v_g_ebughu_deluge_icaf_gbp double precision;
  v_g_ebughu_deluge_maximum_reasonably_practicable_cost_gbp double precision;
  v_g_ebughu_blast_wall_cost_to_benefit_ratio double precision;
  v_g_ebughu_blast_wall_icaf_gbp double precision;
  v_g_ebughu_gas_detection_cost_to_benefit_ratio double precision;
begin

  -- ---------------------------------------------------------------- shape
  select count(*) into v_structures from public.academy_course_structures
   where app_slug = 'qra' and active;
  if v_structures <> 3 then
    raise exception 'H5 go-live refused: qra has % active deep structures, expected 3', v_structures;
  end if;

  select count(*) into v_questions from public.academy_quiz_questions where app_slug = 'qra';
  if v_questions <> 396 then
    raise exception 'H5 go-live refused: qra has % quiz questions, expected 396', v_questions;
  end if;

  select count(*) into v_n from (
    select tier from public.academy_quiz_questions where app_slug = 'qra'
     group by tier having count(*) <> 132) t;
  if v_n <> 0 then
    raise exception 'H5 go-live refused: % tier(s) do not carry exactly 132 questions', v_n;
  end if;

  select count(*) into v_n from (
    select tier, module_key from public.academy_quiz_questions
     where app_slug = 'qra' and scope = 'module'
     group by tier, module_key having count(*) <> 15) t;
  if v_n <> 0 then
    raise exception 'H5 go-live refused: % module bank(s) do not carry exactly 15 questions', v_n;
  end if;

  select count(*) into v_n from (
    select tier from public.academy_quiz_questions
     where app_slug = 'qra' and scope = 'final'
     group by tier having count(*) <> 42) t;
  if v_n <> 0 then
    raise exception 'H5 go-live refused: % final exam(s) do not carry exactly 42 questions', v_n;
  end if;

  -- A key outside its own options is unanswerable, and a count of rows cannot
  -- see it.
  select count(*) into v_n from public.academy_quiz_questions
   where app_slug = 'qra'
     and (jsonb_array_length(options) <> 4 or answer_index < 0 or answer_index > 3);
  if v_n <> 0 then
    raise exception 'H5 go-live refused: % question(s) do not offer four options with a key inside them', v_n;
  end if;

  select count(*) into v_lessons
    from public.academy_course_structures s,
         lateral jsonb_array_elements(s.structure->'modules') m,
         lateral jsonb_array_elements_text(m->'lesson_keys') lk
   where s.app_slug = 'qra' and s.active;
  if v_lessons <> 78 then
    raise exception 'H5 go-live refused: qra carries % lesson keys, expected 78', v_lessons;
  end if;

  select count(*) into v_modules
    from public.academy_course_structures s,
         lateral jsonb_array_elements(s.structure->'modules') m
   where s.app_slug = 'qra' and s.active;
  if v_modules <> 18 then
    raise exception 'H5 go-live refused: qra carries % modules, expected 18 (six per tier)', v_modules;
  end if;

  select count(*) into v_n from (
    select distinct qq.tier, qq.module_key from public.academy_quiz_questions qq
     where qq.app_slug = 'qra' and qq.scope = 'module'
       and not exists (
         select 1 from public.academy_course_structures s,
              lateral jsonb_array_elements(s.structure->'modules') m
          where s.app_slug = qq.app_slug and s.tier = qq.tier and s.active
            and m->>'key' = qq.module_key)) t;
  if v_n <> 0 then
    raise exception 'H5 go-live refused: % module bank(s) are keyed to a module the structure does not declare', v_n;
  end if;

  select count(*) into v_capstones from public.academy_capstones where app_slug = 'qra';
  if v_capstones <> 3 then
    raise exception 'H5 go-live refused: qra has % capstones, expected 3', v_capstones;
  end if;

  select count(*) into v_graded from public.academy_capstones c,
         lateral jsonb_array_elements(c.fields) f where c.app_slug = 'qra';
  if v_graded <> 18 then
    raise exception 'H5 go-live refused: qra has % graded capstone fields, expected 18', v_graded;
  end if;

  select count(*) into v_n from (
    select c.tier from public.academy_capstones c, lateral jsonb_array_elements(c.fields) f
     where c.app_slug = 'qra' group by c.tier having count(*) <> 6) t;
  if v_n <> 0 then
    raise exception 'H5 go-live refused: % tier(s) do not grade exactly six fields', v_n;
  end if;

  if not exists (select 1 from public.academy_apps
                  where slug = 'qra' and module = 'hse'
                    and path_order = 65 and prereq_slug is null) then
    raise exception 'H5 go-live refused: the qra catalogue row is not hse at path_order 65 with no prerequisite';
  end if;

  if exists (select 1 from public.academy_apps where path_order = 65 and slug <> 'qra') then
    raise exception 'H5 go-live refused: another course already holds path_order 65';
  end if;

  -- ------------------------------------------------- the grader is numeric
  -- Every field a positive, non-whole number at its class's tolerance (twelve
  -- decimals at 5e-13, six at 5e-7, two at 0.005), with a label and a unit.
  select count(*), string_agg(c.tier || '/' || (f->>'key'), ', ')
    into v_n, v_names
    from public.academy_capstones c, lateral jsonb_array_elements(c.fields) f
   where c.app_slug = 'qra'
     and (jsonb_typeof(f->'expected') <> 'number' or jsonb_typeof(f->'tol') <> 'number'
          or (f->>'expected')::numeric <= 0
          or (f->>'expected')::numeric = round((f->>'expected')::numeric)
          or (f->>'tol')::numeric <> case when f->>'key' in ('ogini_crew_far', 'ogini_village_vrom_max_ratio', 'ogini_village_exceedance_from_fatalities', 'ogini_village_r2p2_point_ratio', 'ebughu_deluge_cost_to_benefit_ratio', 'ebughu_blast_wall_cost_to_benefit_ratio', 'ebughu_gas_detection_cost_to_benefit_ratio') then 0.0000005
                                          when f->>'key' in ('ebughu_deluge_icaf_gbp', 'ebughu_deluge_maximum_reasonably_practicable_cost_gbp', 'ebughu_blast_wall_icaf_gbp') then 0.005
                                          else 0.0000000000005 end
          or (f->>'key') not in ('ukpokiti_compressor_explosion_frequency_per_yr', 'ukpokiti_camp_exposure_frequency_per_yr', 'ukpokiti_control_room_lsir_per_yr', 'ukpokiti_compressor_deck_lsir_per_yr', 'ukpokiti_operator_irpa_per_yr', 'ukpokiti_technician_irpa_per_yr', 'ogini_crew_pll_per_yr', 'ogini_crew_far', 'ogini_village_frequency_ten_or_more_per_yr', 'ogini_village_vrom_max_ratio', 'ogini_village_exceedance_from_fatalities', 'ogini_village_r2p2_point_ratio', 'ebughu_deluge_cost_to_benefit_ratio', 'ebughu_deluge_icaf_gbp', 'ebughu_deluge_maximum_reasonably_practicable_cost_gbp', 'ebughu_blast_wall_cost_to_benefit_ratio', 'ebughu_blast_wall_icaf_gbp', 'ebughu_gas_detection_cost_to_benefit_ratio')
          or coalesce(f->>'label', '') = '' or coalesce(f->>'unit', '') = '');
  if v_n <> 0 then
    raise exception 'H5 go-live refused: % graded field(s) are not a positive non-whole number at their class tolerance with a label and a unit: %', v_n, v_names;
  end if;

  -- THE GRADER, SIMULATED ON THE SEEDED ROW. The answer the prompt asks for,
  -- the expected value to its class's decimals, must pass
  -- abs(answer - expected) <= tol in numeric exactly as academy_submit_capstone
  -- computes it, and one unit in the last decimal either side of it must fail.
  select count(*), string_agg(t.tier || '/' || t.k, ', ')
    into v_n, v_names
    from (select c.tier, f->>'key' k, (f->>'expected')::numeric e, (f->>'tol')::numeric tl,
                 case when f->>'key' in ('ogini_crew_far', 'ogini_village_vrom_max_ratio', 'ogini_village_exceedance_from_fatalities', 'ogini_village_r2p2_point_ratio', 'ebughu_deluge_cost_to_benefit_ratio', 'ebughu_blast_wall_cost_to_benefit_ratio', 'ebughu_gas_detection_cost_to_benefit_ratio') then 6 when f->>'key' in ('ebughu_deluge_icaf_gbp', 'ebughu_deluge_maximum_reasonably_practicable_cost_gbp', 'ebughu_blast_wall_icaf_gbp') then 2 else 12 end dp
            from public.academy_capstones c, lateral jsonb_array_elements(c.fields) f
           where c.app_slug = 'qra') t
   where abs(round(t.e, t.dp) - t.e) > t.tl
      or abs(round(t.e, t.dp) + power(10::numeric, -t.dp) - t.e) <= t.tl
      or abs(round(t.e, t.dp) - power(10::numeric, -t.dp) - t.e) <= t.tl;
  if v_n <> 0 then
    raise exception 'H5 go-live refused: % graded field(s) either fail the answer the prompt asks for or pass one a unit off in its last decimal: %', v_n, v_names;
  end if;


  -- ---------------------------------------- the prompts the learner reads

  -- beginner: the rendered prompt, byte for byte, and the dataset and title.
  select prompt into v_prompt from public.academy_capstones where app_slug = 'qra' and tier = 'beginner';
  if md5(v_prompt) <> '9e67df64d1ad7447391effc5db3141ef' then
    raise exception 'H5 go-live refused: the beginner prompt is not the prompt gen_course.py rendered from the engine inputs (md5 %)', md5(v_prompt);
  end if;
  if not exists (select 1 from public.academy_capstones where app_slug = 'qra' and tier = 'beginner'
                    and cert_tier = 'associate' and dataset = 'UKPOKITI, an onshore gas compression station and its camp' and title = 'How often each outcome happens, and what one person carries') then
    raise exception 'H5 go-live refused: the beginner capstone does not carry the certificate tier, dataset and title gen_course.py rendered';
  end if;
  -- Every input fragment the second route reads is stated, matched as a
  -- literal substring with strpos (an underscore or a percent sign in a LIKE
  -- pattern is a wildcard).
  select count(*) into v_n from unnest(array['UKPOKITI, an onshore gas compression station with a workers'' camp. Every frequency is per year and every probability is a fraction. Every probability of death below is stated from the station''s consequence study, for a person present outdoors and unprotected at the place, and this capstone takes it as given.', 'COMPRESSOR RELEASE: a continuous gas release in the compressor module at 0.00038 per year. Immediate ignition probability 0.15, giving the outcome ''jet or pool fire''; delayed ignition probability 0.37 GIVEN no immediate ignition, a delayed ignition burning as a ''flash fire'' with probability 0.6 or as an ''explosion'' with probability 0.4; otherwise ''no ignition''.', 'SOUR GAS RELEASE: a sour gas release at the inlet manifold at 0.0017 per year, with the branches ''isolated in time'' 0.88 (outcome ''no camp exposure''); or ''isolated late'' 0.08, then ''wind toward the camp'' 0.18 (outcome ''camp exposure'') or ''wind away from the camp'' 0.82 (outcome ''no camp exposure''); or ''not isolated'' 0.04, then ''wind toward the camp'' 0.31 (outcome ''camp exposure'') or ''wind away from the camp'' 0.69 (outcome ''no camp exposure'').', 'PROBABILITY OF DEATH BY PLACE: in the control room ''jet or pool fire'' 0.04, ''flash fire'' 0 and ''explosion'' 0.12; on the compressor deck ''jet or pool fire'' 0.65, ''flash fire'' 1 and ''explosion'' 0.85; in the camp ''camp exposure'' 0.26 and ''explosion'' 0.004. An outcome not listed at a place kills no one there.', 'OPERATOR: 730 hours a year on the compressor deck, 1095 hours in the control room and 2555 hours in the camp. TECHNICIAN: 0.12 of the year on the compressor deck, 400 hours in the control room and 3980 hours in the camp. A year is 8760 hours, and no vulnerability factor is applied.']) l where strpos(v_prompt, l) = 0;
  if v_n <> 0 then
    raise exception 'H5 go-live refused: % beginner input fragment(s) the second route reads are not stated in the shipped prompt', v_n;
  end if;

  -- intermediate: the rendered prompt, byte for byte, and the dataset and title.
  select prompt into v_prompt from public.academy_capstones where app_slug = 'qra' and tier = 'intermediate';
  if md5(v_prompt) <> '50750a6623314a6cadd805da54b8b943' then
    raise exception 'H5 go-live refused: the intermediate prompt is not the prompt gen_course.py rendered from the engine inputs (md5 %)', md5(v_prompt);
  end if;
  if not exists (select 1 from public.academy_capstones where app_slug = 'qra' and tier = 'intermediate'
                    and cert_tier = 'professional' and dataset = 'OGINI, a gas terminal beside a village' and title = 'How many at once: the crew and the village') then
    raise exception 'H5 go-live refused: the intermediate capstone does not carry the certificate tier, dataset and title gen_course.py rendered';
  end if;
  -- Every input fragment the second route reads is stated, matched as a
  -- literal substring with strpos (an underscore or a percent sign in a LIKE
  -- pattern is a wildcard).
  select count(*) into v_n from unnest(array['OGINI, a gas terminal beside a village. Every frequency is per year. The expected number of deaths of each scenario, N, is stated from the terminal''s consequence study and need not be whole; this capstone takes it as given.', 'CREW: ''separator fire'' 0.0043 per year with N = 1.7; ''compressor house explosion'' 0.00061 per year with N = 7.3; ''dropped object during a lift'' 0.022 per year with N = 0.45; ''riser rupture with escalation'' 9.5e-5 per year with N = 21; ''small fire, put out'' 0.034 per year with N = 0. The crew roster is 70 people, each exposed 2184 hours a year.', 'VILLAGE: ''LPG sphere BLEVE'' 3.74e-7 per year with N = 140; ''propane cloud flash fire reaching the village'' 4.53e-6 per year with N = 55; ''H2S cloud reaching the village'' 1.31e-5 per year with N = 10; ''jet fire at the fence'' 4.4e-5 per year with N = 2.5; ''small release, no one reached'' 9.1e-5 per year with N = 0.', 'Compare the village curve with the line the engine calls vrom-establishments, the Purple Book Figure 6.8 line F = 0.001 / N^2 per year for N of 10 or more, on which the three Bevi points lie; and with the point the engine calls r2p2-para-136, the single R2P2 point of 50 or more deaths at 1 in 5000 per year. Read the curve as the frequency of N OR MORE deaths. The step of the village curve that ends at N = 55 is the one the fifth value asks about.']) l where strpos(v_prompt, l) = 0;
  if v_n <> 0 then
    raise exception 'H5 go-live refused: % intermediate input fragment(s) the second route reads are not stated in the shipped prompt', v_n;
  end if;

  -- advanced: the rendered prompt, byte for byte, and the dataset and title.
  select prompt into v_prompt from public.academy_capstones where app_slug = 'qra' and tier = 'advanced';
  if md5(v_prompt) <> '8e8a5a19969ef556393aceaed41b8a82' then
    raise exception 'H5 go-live refused: the advanced prompt is not the prompt gen_course.py rendered from the engine inputs (md5 %)', md5(v_prompt);
  end if;
  if not exists (select 1 from public.academy_capstones where app_slug = 'qra' and tier = 'advanced'
                    and cert_tier = 'expert' and dataset = 'EBUGHU, three proposed measures at a gas processing plant' and title = 'Which measures are reasonably practicable') then
    raise exception 'H5 go-live refused: the advanced capstone does not carry the certificate tier, dataset and title gen_course.py rendered';
  end if;
  -- Every input fragment the second route reads is stated, matched as a
  -- literal substring with strpos (an underscore or a percent sign in a LIKE
  -- pattern is a wildcard).
  select count(*) into v_n from unnest(array['EBUGHU, a gas processing plant weighing three proposed risk reduction measures by the HSE gross disproportion test. Every PLL reduction is stated from the plant''s own assessment. The values of preventing a fatality are the HSE''s published figures, used here for illustration only: 1336800 GBP at 2003 prices and 1000000 GBP at 2001 prices.', 'DELUGE, a deluge system on the compressor module: a PLL reduction of 0.0031 fatalities per year, a VPF of 1336800 GBP, other harms prevented: ''serious injury'' 0.012 cases a year at 20500 GBP a case and ''slight injury'' 0.05 cases a year at 300 GBP a case, a life of 20 years, a capital cost of 21000 GBP at year 0 and 600 GBP at the end of each year, a disproportion factor of 6, benefits discounted at 0.015 a year and costs at 0.035 a year, every flow at the end of its year.', 'BLAST WALL, a blast wall between the process area and the control building: a PLL reduction of 0.00084 fatalities per year, a VPF of 1000000 GBP, no other harm counted, a life of 25 years, a capital cost of 2900000 GBP at year 0, a disproportion factor of 3, benefits discounted at 0.06 a year and costs at 0.06 a year, the benefit uprated by 0.04 a year, every flow at the end of its year.', 'GAS DETECTION, an upgrade of the gas detection: a PLL reduction of 0.00047 fatalities per year, a VPF of 1336800 GBP, no other harm counted, a life of 15 years, a capital cost of 72300 GBP at year 0 and 4100 GBP at the end of each year, a disproportion factor of 10, undiscounted, every rate zero.', 'Count the fatalities prevented undiscounted, the PLL reduction times the life in years.']) l where strpos(v_prompt, l) = 0;
  if v_n <> 0 then
    raise exception 'H5 go-live refused: % advanced input fragment(s) the second route reads are not stated in the shipped prompt', v_n;
  end if;

  -- --------------------------------------- the eighteen graded values
  select (f->>'expected')::double precision into v_g_ukpokiti_compressor_explosion_frequency_per_yr
    from public.academy_capstones c, lateral jsonb_array_elements(c.fields) f
   where c.app_slug = 'qra' and c.tier = 'beginner' and f->>'key' = 'ukpokiti_compressor_explosion_frequency_per_yr';
  select (f->>'expected')::double precision into v_g_ukpokiti_camp_exposure_frequency_per_yr
    from public.academy_capstones c, lateral jsonb_array_elements(c.fields) f
   where c.app_slug = 'qra' and c.tier = 'beginner' and f->>'key' = 'ukpokiti_camp_exposure_frequency_per_yr';
  select (f->>'expected')::double precision into v_g_ukpokiti_control_room_lsir_per_yr
    from public.academy_capstones c, lateral jsonb_array_elements(c.fields) f
   where c.app_slug = 'qra' and c.tier = 'beginner' and f->>'key' = 'ukpokiti_control_room_lsir_per_yr';
  select (f->>'expected')::double precision into v_g_ukpokiti_compressor_deck_lsir_per_yr
    from public.academy_capstones c, lateral jsonb_array_elements(c.fields) f
   where c.app_slug = 'qra' and c.tier = 'beginner' and f->>'key' = 'ukpokiti_compressor_deck_lsir_per_yr';
  select (f->>'expected')::double precision into v_g_ukpokiti_operator_irpa_per_yr
    from public.academy_capstones c, lateral jsonb_array_elements(c.fields) f
   where c.app_slug = 'qra' and c.tier = 'beginner' and f->>'key' = 'ukpokiti_operator_irpa_per_yr';
  select (f->>'expected')::double precision into v_g_ukpokiti_technician_irpa_per_yr
    from public.academy_capstones c, lateral jsonb_array_elements(c.fields) f
   where c.app_slug = 'qra' and c.tier = 'beginner' and f->>'key' = 'ukpokiti_technician_irpa_per_yr';
  select (f->>'expected')::double precision into v_g_ogini_crew_pll_per_yr
    from public.academy_capstones c, lateral jsonb_array_elements(c.fields) f
   where c.app_slug = 'qra' and c.tier = 'intermediate' and f->>'key' = 'ogini_crew_pll_per_yr';
  select (f->>'expected')::double precision into v_g_ogini_crew_far
    from public.academy_capstones c, lateral jsonb_array_elements(c.fields) f
   where c.app_slug = 'qra' and c.tier = 'intermediate' and f->>'key' = 'ogini_crew_far';
  select (f->>'expected')::double precision into v_g_ogini_village_frequency_ten_or_more_per_yr
    from public.academy_capstones c, lateral jsonb_array_elements(c.fields) f
   where c.app_slug = 'qra' and c.tier = 'intermediate' and f->>'key' = 'ogini_village_frequency_ten_or_more_per_yr';
  select (f->>'expected')::double precision into v_g_ogini_village_vrom_max_ratio
    from public.academy_capstones c, lateral jsonb_array_elements(c.fields) f
   where c.app_slug = 'qra' and c.tier = 'intermediate' and f->>'key' = 'ogini_village_vrom_max_ratio';
  select (f->>'expected')::double precision into v_g_ogini_village_exceedance_from_fatalities
    from public.academy_capstones c, lateral jsonb_array_elements(c.fields) f
   where c.app_slug = 'qra' and c.tier = 'intermediate' and f->>'key' = 'ogini_village_exceedance_from_fatalities';
  select (f->>'expected')::double precision into v_g_ogini_village_r2p2_point_ratio
    from public.academy_capstones c, lateral jsonb_array_elements(c.fields) f
   where c.app_slug = 'qra' and c.tier = 'intermediate' and f->>'key' = 'ogini_village_r2p2_point_ratio';
  select (f->>'expected')::double precision into v_g_ebughu_deluge_cost_to_benefit_ratio
    from public.academy_capstones c, lateral jsonb_array_elements(c.fields) f
   where c.app_slug = 'qra' and c.tier = 'advanced' and f->>'key' = 'ebughu_deluge_cost_to_benefit_ratio';
  select (f->>'expected')::double precision into v_g_ebughu_deluge_icaf_gbp
    from public.academy_capstones c, lateral jsonb_array_elements(c.fields) f
   where c.app_slug = 'qra' and c.tier = 'advanced' and f->>'key' = 'ebughu_deluge_icaf_gbp';
  select (f->>'expected')::double precision into v_g_ebughu_deluge_maximum_reasonably_practicable_cost_gbp
